package org.apache.druid.server.metrics;

import com.google.inject.Inject;
import com.google.inject.Injector;
import org.apache.druid.discovery.NodeRole;
import org.apache.druid.guice.annotations.Self;
import org.apache.druid.java.util.emitter.service.ServiceEmitter;
import org.apache.druid.java.util.emitter.service.ServiceMetricEvent;
import org.apache.druid.java.util.metrics.AbstractMonitor;
import org.apache.druid.query.DruidMetrics;

import java.util.Map;
import java.util.Set;

public class WorkerTaskCountStatsMonitor extends AbstractMonitor
{
  private final WorkerTaskCountStatsProvider statsProvider;
  private final IndexerTaskCountStatsProvider indexerStatsProvider;
  private final String workerCategory;
  private final String workerVersion;
  private final boolean isMiddleManager;

  @Inject
  public WorkerTaskCountStatsMonitor(
      Injector injector,
      @Self Set<NodeRole> nodeRoles
  )
  {
    this.isMiddleManager = nodeRoles.contains(NodeRole.MIDDLE_MANAGER);
    if (isMiddleManager) {
      this.statsProvider = injector.getInstance(WorkerTaskCountStatsProvider.class);
      this.indexerStatsProvider = null;
      this.workerCategory = statsProvider.getWorkerCategory();
      this.workerVersion = statsProvider.getWorkerVersion();
    } else {
      this.indexerStatsProvider = injector.getInstance(IndexerTaskCountStatsProvider.class);
      this.statsProvider = null;
      this.workerCategory = null;
      this.workerVersion = null;
    }
  }

  @Override
  public boolean doMonitor(ServiceEmitter emitter)
  {
    if (isMiddleManager) {
      String category = workerCategory;
      String resolvedCategory = statsProvider.resolvedWorkerCategory();
      if (resolvedCategory != null) {
        category = resolvedCategory;
      }
      String version = workerVersion;
      String resolvedVersion = statsProvider.resolvedWorkerVersion();
      if (resolvedVersion != null) {
        version = resolvedVersion;
      }

      Long failedTaskCount = statsProvider.getWorkerFailedTaskCount();
      if (failedTaskCount != null) {
        ServiceMetricEvent.Builder failedBuilder = new ServiceMetricEvent.Builder();
        failedBuilder.setDimension(DruidMetrics.CATEGORY, category);
        failedBuilder.setDimension(DruidMetrics.WORKER_VERSION, version);
        emitter.emit(failedBuilder.setMetric("worker/task/failed/count", failedTaskCount));
      }
      Long successfulTaskCount = statsProvider.getWorkerSuccessfulTaskCount();
      if (successfulTaskCount != null) {
        ServiceMetricEvent.Builder successBuilder = new ServiceMetricEvent.Builder();
        successBuilder.setDimension(DruidMetrics.CATEGORY, category);
        successBuilder.setDimension(DruidMetrics.WORKER_VERSION, version);
        emitter.emit(successBuilder.setMetric("worker/task/success/count", successfulTaskCount));
      }
      Long idleTaskSlotCount = statsProvider.getWorkerIdleTaskSlotCount();
      if (idleTaskSlotCount != null) {
        ServiceMetricEvent.Builder idleBuilder = new ServiceMetricEvent.Builder();
        idleBuilder.setDimension(DruidMetrics.CATEGORY, category);
        idleBuilder.setDimension(DruidMetrics.WORKER_VERSION, version);
        emitter.emit(idleBuilder.setMetric("worker/taskSlot/idle/count", idleTaskSlotCount));
      }
      Long totalTaskSlotCount = statsProvider.getWorkerTotalTaskSlotCount();
      if (totalTaskSlotCount != null) {
        ServiceMetricEvent.Builder totalBuilder = new ServiceMetricEvent.Builder();
        totalBuilder.setDimension(DruidMetrics.CATEGORY, category);
        totalBuilder.setDimension(DruidMetrics.WORKER_VERSION, version);
        emitter.emit(totalBuilder.setMetric("worker/taskSlot/total/count", totalTaskSlotCount));
      }
      Long usedTaskSlotCount = statsProvider.getWorkerUsedTaskSlotCount();
      if (usedTaskSlotCount != null) {
        ServiceMetricEvent.Builder usedBuilder = new ServiceMetricEvent.Builder();
        usedBuilder.setDimension(DruidMetrics.CATEGORY, category);
        usedBuilder.setDimension(DruidMetrics.WORKER_VERSION, version);
        emitter.emit(usedBuilder.setMetric("worker/taskSlot/used/count", usedTaskSlotCount));
      }
    } else {
      for (Map.Entry<String, Long> runningEntry : indexerStatsProvider.getWorkerRunningTasks().entrySet()) {
        Long runningCount = runningEntry.getValue();
        if (runningCount != null) {
          String runningDataSource = indexerStatsProvider.resolvedDataSourceDimension(runningEntry.getKey());
          if (runningDataSource == null) {
            runningDataSource = runningEntry.getKey();
          }
          ServiceMetricEvent.Builder runningBuilder = new ServiceMetricEvent.Builder();
          runningBuilder.setDimension(DruidMetrics.DATASOURCE, runningDataSource);
          emitter.emit(runningBuilder.setMetric("worker/task/running/count", runningCount));
        }
      }
      for (Map.Entry<String, Long> assignedEntry : indexerStatsProvider.getWorkerAssignedTasks().entrySet()) {
        Long assignedCount = assignedEntry.getValue();
        if (assignedCount != null) {
          String assignedDataSource = indexerStatsProvider.resolvedDataSourceDimension(assignedEntry.getKey());
          if (assignedDataSource == null) {
            assignedDataSource = assignedEntry.getKey();
          }
          ServiceMetricEvent.Builder assignedBuilder = new ServiceMetricEvent.Builder();
          assignedBuilder.setDimension(DruidMetrics.DATASOURCE, assignedDataSource);
          emitter.emit(assignedBuilder.setMetric("worker/task/assigned/count", assignedCount));
        }
      }
      emit(emitter, "worker/task/completed/count", indexerStatsProvider.getWorkerCompletedTasks());
      emit(emitter, "worker/task/failed/count", indexerStatsProvider.getWorkerFailedTasks());
      emit(emitter, "worker/task/success/count", indexerStatsProvider.getWorkerSuccessfulTasks());
    }
    return true;
  }

  public void emit(ServiceEmitter emitter, String metricName, Map<String, Long> dataSourceTaskMap)
  {
    for (Map.Entry<String, Long> dataSourceTaskCount : dataSourceTaskMap.entrySet()) {
      if (dataSourceTaskCount.getValue() != null) {
        ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
        builder.setDimension(DruidMetrics.DATASOURCE, dataSourceTaskCount.getKey());
        emitter.emit(builder.setMetric(metricName, dataSourceTaskCount.getValue()));
      }
    }
  }
}

